{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Restrictable SageMaker action applies to all resources",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy permits CreatePresignedNotebookInstanceUrl against Resource "*", allowing presigned access to every notebook instance accessible in the account. This action supports notebook-instance-level resource scoping."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Sensitive SageMaker access is granted without resource constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "Creating a presigned notebook URL can grant access to a notebook and its execution-role privileges, but the policy does not constrain the target notebook. An exact notebook instance ARN is required to limit this access."
    }
  ],
  "patched_code": "variable "sagemaker_notebook_instance_arn" {
  description = "ARN of the SageMaker notebook instance for which presigned URLs may be created"
  type        = string

  validation {
    condition     = can(regex("^arn:[^:]+:sagemaker:[^:]+:[0-9]{12}:notebook-instance/[A-Za-z0-9-]+$", var.sagemaker_notebook_instance_arn))
    error_message = "The SageMaker notebook instance ARN must identify one specific notebook instance and must not contain wildcards."
  }
}

resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl"
        ]
        Resource = var.sagemaker_notebook_instance_arn
      },
      {
        Effect = "Allow"
        Action = [
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "*"
      }
    ]
  })
}
",
  "fix_summary": "Split the resource-scoped URL creation action from the list action and restricted it to a validated, exact notebook instance ARN. ListNotebookInstances retains Resource "*" because that list action does not support resource-level permissions."
}
